def countVowelsBeforeConsonant(s, ch):
    vowels = set('aeiou')
    ch = ch.lower()
    s_low = s.lower()
    count = 0
    for i in range(len(s_low) - 1):
        if s_low[i] in vowels and s_low[i + 1] == ch:
            count += 1
    return count

def factorialDigitSum(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return sum(int(d) for d in str(result))

def capitalizeAlternateWords(s):
    words = s.split(' ')
    result = []
    for i, w in enumerate(words):
        if i % 2 == 0 and w:
            result.append(w[0].upper() + w[1:].lower())
        else:
            result.append(w)
    return ' '.join(result)

def removeDuplicatesKeepLast(arr):
    last_idx = {}
    for i, x in enumerate(arr):
        last_idx[x] = i
    return [x for x, i in sorted(last_idx.items(), key=lambda kv: kv[1])]

def countRunsOfChar(s, ch):
    count = 0
    prev = None
    for c in s:
        if c == ch and prev != ch:
            count += 1
        prev = c
    return count

def gcdOfList(nums):
    def gcd2(a, b):
        while b:
            a, b = b, a % b
        return a
    result = 0
    for n in nums:
        result = gcd2(result, n)
    return result

def isValidNestedWithBudget(s, maxDepth):
    depth = 0
    max_seen = 0
    for c in s:
        if c == '(':
            depth += 1
            max_seen = max(max_seen, depth)
        elif c == ')':
            depth -= 1
            if depth < 0:
                return False
        else:
            return False
    if depth != 0:
        return False
    return max_seen <= maxDepth

def mergeSortedCapped(a, b, cap):
    i, j = 0, 0
    out = []
    while i < len(a) and j < len(b) and len(out) < cap:
        if a[i] <= b[j]:
            out.append(a[i]); i += 1
        else:
            out.append(b[j]); j += 1
    while i < len(a) and len(out) < cap:
        out.append(a[i]); i += 1
    while j < len(b) and len(out) < cap:
        out.append(b[j]); j += 1
    return out

def longestCommonSuffix(strs):
    if not strs:
        return ''
    suffix = strs[0]
    for s in strs[1:]:
        while not s.lower().endswith(suffix.lower()):
            suffix = suffix[1:]
            if not suffix:
                return ''
    return suffix

def kthLargestUnique(nums, k):
    distinct = sorted(set(nums), reverse=True)
    if k > len(distinct):
        return None
    return distinct[k - 1]

def antiTranspose(matrix):
    n = len(matrix)
    m = len(matrix[0]) if n else 0
    result = [[None] * n for _ in range(m)]
    for i in range(n):
        for j in range(m):
            result[m - 1 - j][n - 1 - i] = matrix[i][j]
    return result

def findMissingInRange(nums, lo, hi):
    total = (hi - lo + 1) * (lo + hi) // 2
    return total - sum(nums)

def integerNthRoot(n, k):
    if n < 2:
        return n
    lo, hi = 1, n
    ans = 1
    while lo <= hi:
        mid = (lo + hi) // 2
        val = mid ** k
        if val <= n:
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

def longestIncreasingSubsequenceWithMaxGap(nums, maxGap):
    n = len(nums)
    if n == 0:
        return 0
    dp = [1] * n
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i] and nums[i] - nums[j] <= maxGap:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

def minSemestersToFinish(numCourses, prerequisites):
    from collections import deque
    graph = {i: [] for i in range(numCourses)}
    indegree = [0] * numCourses
    for a, b in prerequisites:
        graph[b].append(a)
        indegree[a] += 1
    queue = deque([i for i in range(numCourses) if indegree[i] == 0])
    taken = 0
    semesters = 0
    while queue:
        semesters += 1
        for _ in range(len(queue)):
            node = queue.popleft()
            taken += 1
            for nxt in graph[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    queue.append(nxt)
    return semesters if taken == numCourses else -1

def longestPalindromicSubsequenceLength(s):
    t = s[0::2]
    n = len(t)
    if n == 0:
        return 0
    dp = [[0] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        dp[i][i] = 1
        for j in range(i + 1, n):
            if t[i] == t[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2 if j > i + 1 else 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
    return dp[0][n - 1]

def categoryScopedCacheOps(categoryCapacities, operations):
    from collections import OrderedDict
    caches = {cat: OrderedDict() for cat in categoryCapacities}
    out = []
    for op in operations:
        kind, cat = op[0], op[1]
        cache = caches[cat]
        cap = categoryCapacities[cat]
        if kind == 'put':
            key, value = op[2], op[3]
            if key in cache:
                cache.move_to_end(key)
            cache[key] = value
            if len(cache) > cap:
                cache.popitem(last=False)
            out.append(None)
        else:
            key = op[2]
            if key in cache:
                cache.move_to_end(key)
                out.append(cache[key])
            else:
                out.append(-1)
    return out
